class MockLockFile:
    def __init__(self):
        self.data = {
            "dependencies": [
                {"name": "requests", "version": "2.28.1", "source": "pypi"},
                {"name": "click", "version": "8.1.3", "source": "pypi"}
            ],
            "groups": {
                "default": ["requests", "click"]
            }
        }

    def select(self, environment, tags, extras, dependency_groups, prefer_sdist_predicate):
        # Simplified selection logic for demonstration
        if not dependency_groups:
            dependency_groups = ["default"]

        selected = []
        for group in dependency_groups:
            if group in self.data["groups"]:
                for dep_name in self.data["groups"][group]:
                    for dep in self.data["dependencies"]:
                        if dep["name"] == dep_name:
                            selected.append(dep)
        return selected

mock_lock = MockLockFile()
environment = default_environment()
tags = list(sys_tags())
extras = []
dependency_groups = ["default"]
